use super::*;
#[kani::proof]
#[kani::unwind(34)]
#[kani::stub(core::ptr::copy_nonoverlapping,crate::NFO_KMX::KMX_copy_nonoverlapping)]
#[kani::stub(<[u8]>::copy_from_slice,crate::NFO_KMX::KMX_copy_from_slice)]
fn association(){let key=Pubkey::new_from_array(kani::any());let signer:bool=kani::any();let j:usize=kani::any();kani::assume(j<32);let byte=key.to_bytes()[j];let mut meta=AccountMeta::new_readonly(key,signer);let mut wrong=meta.pubkey.to_bytes();wrong[j]^=1;meta.pubkey=Pubkey::new_from_array(wrong);assert!(meta.pubkey.to_bytes()[j]==byte&&meta.is_signer==signer&&!meta.is_writable);}
